W,H=1600,900
img=[[(23,27,42) for _ in range(W)] for _ in range(H)]

def rect(x,y,w,h,c):
  for j in range(max(0,y),min(H,y+h)):
    row=img[j]
    for i in range(max(0,x),min(W,x+w)): row[i]=c

